INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R05','Condiciones financieras','Cargos iniciales','«Cargos iniciales: Eliminados.»','conceptos iniciales incluidos en la oferta','=','eliminados','No incorporarlos en la oferta','No extender la eliminación a otros conceptos sin definición.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Catálogo financiero','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,5,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R05');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R06','Condiciones financieras','Control de oferta','«el Costo Financiero Total Efectivo Anual (CFTEA) de los préstamos no puede superar el tope del 131%.»','flujos y CFTEA calculado','<=','131% (parámetro documental)','Controlar la oferta contra el tope','Fórmula y tratamiento de exceso por acordar. No se afirma vigencia normativa externa ni cumplimiento por usar tasa 7,2%.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Parametrización y cálculo financiero por definir','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,6,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R06');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R07','BCRA','Exclusiones de cálculo','«no se deben contabilizar las deudas de las siguientes entidades del grupo: CELESOL (55281), FIAT (55277) y Mutual de Socios de la Asociación Médica de Rosario (72104).»','código de entidad, situación y monto BCRA','no en lista','{55281, 55277, 72104}','Excluir sus deudas del cálculo indicado','Conservar entradas originales. Alcance sobre conteos, situaciones y ausencia de historial pendiente. No extender a otras entidades.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','BCRA (CredixSA)','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,7,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R07');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R08','BCRA','Situación 1','«Situación 1 o Sin registro en BCRA: El socio es Apto para operar en condiciones plenas.»','situaciones por entidad','=','situación 1','Continuar','No se implementa como aprobación global anticipada; no omite entidades, deuda total ni demás controles.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','BCRA (CredixSA)','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,8,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R08');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R09','BCRA','Sin registro','«Situación 1 o Sin registro en BCRA: El socio es Apto para operar en condiciones plenas.»','resultado de consulta e historial','=','consulta válida sin registro (no error ni faltante)','Continuar con controles restantes','Aplicar SF-R15/SF-R16 cuando correspondan. Alcance de «sin historial» pendiente.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','BCRA; semántica técnica pendiente','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,9,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R09');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R10','BCRA','Construcción de deuda irregular','«Deuda Irregular (Suma de montos en situación 2, 3, 4 y 5 juntas)».','entidad, situación y monto BCRA','suma','situaciones {2,3,4,5}','Variable para SF-R11; no decide sola','Aplicar exclusiones que se confirmen. No confundir saldo informado con cuotas vencidas.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','BCRA (CredixSA)','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,10,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R10');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R11','BCRA','Deuda irregular / neto','Cuerpo: «Menor a 2 sueldos netos: Apto»; «Mayor a 2 sueldos netos: No opera (Rechazo).» Resumen: «Igual o mayor a 2 salarios netos / No opera».','deuda irregular BCRA + neto del recibo','>','2 × neto (igualdad pendiente)','< 2: apto en esta regla; > 2: rechazo','Igualdad: el cuerpo no la resuelve y el resumen rechaza. No activar esa rama hasta SF-D05.','Estado original: CT. Propuesta funcional BORRADOR, no validada.','BCRA + recibo','CONTRADICCION_A_RESOLVER'::policy_rule_status,'No especificada',false,false,11,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R11');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R12','BCRA','Cantidad de entidades','«Si el socio registra 7 o más entidades con deuda informada, la operación se rechaza.»','entidades con deuda, identificadores y período','>=','7','Rechazo','Menos de 7: continuar este control, no aprobación global. Población y efecto de exclusiones pendientes.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','BCRA (CredixSA)','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,12,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R12');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R13','BCRA','Endeudamiento total','«No debe superar 10 salarios netos. En primera instancia no opera. Casos especiales, revisado por Comité.»','deuda total evaluable y neto','>','10 × neto','No opera en primera instancia','Excepción prevista: casos especiales revisados por Comité (circuito separado). Pendiente si devuelve rechazo revisable o derivación.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','BCRA + recibo','PENDIENTE_VALIDACION'::policy_rule_status,'Prevista: Comité (casos especiales)',true,true,13,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R13');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R14','Elegibilidad','Quiebras y concursos','«Quiebras y Concursos: No opera. No debe registrar ninguno (sin excepciones).»','existencia y evidencia del registro','=','registra quiebra o concurso','No opera','Excepción prohibida expresamente. No habilitar Comité de SF-R13. Fuente no identificada; no presumir Central de Deudores.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Fuente por definir','PENDIENTE_VALIDACION'::policy_rule_status,'Prohibida expresamente',false,false,14,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R14');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R15','Límite especial','Nuevo sin historial BCRA','«Socio nuevo sin historial BCRA: Tope de $1.000.000 y minimo 18 cuotas.»','condición de nuevo, historial, monto','<=','1000000','Limitar monto','No sustituye los demás controles. El resumen no explicita «nuevo»; alcance pendiente.','Estado original: CT. Propuesta funcional BORRADOR, no validada.','Sistema de socios + BCRA + oferta','CONTRADICCION_A_RESOLVER'::policy_rule_status,'No especificada',false,false,15,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R15');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R16','Límite especial','Nuevo sin historial BCRA','«Socio nuevo sin historial BCRA: Tope de $1.000.000 y minimo 18 cuotas.»','nuevo, historial y cuotas','>=','18 cuotas','Limitar plazo','Se combina con máximo por cargo y edad. No confundir mínimo de plazo con aprobación.','Estado original: CT. Propuesta funcional BORRADOR, no validada.','Datos de socio + BCRA + oferta','CONTRADICCION_A_RESOLVER'::policy_rule_status,'No especificada',false,false,16,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R16');
