INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R19','Capacidad','Sueldo remanente','«El sueldo posterior a nuestro descuento no puede ser inferior a 1,5 Salarios Mínimos Vitales y Móviles (SMVM).»','remanente y SMVM vigente','<','1,5 × SMVM aplicable','No opera según resumen; restringe cuota/oferta','No se fija valor monetario del SMVM ni fórmula del neto.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Recibo/cálculo + parámetro SMVM a definir','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,19,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R19');
