INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R21','Recibo','Sin CAJA, MUCI ni MÉDICA','«Si el recibo NO incluye CAJA, MUCI ni MÉDICA: El socio puede tener hasta 5 entidades.»','entidades descontantes del recibo','>','5 entidades','No se aprueba, sujeto a revisión de criterio','El resumen asocia «sin» esas entidades con > 2. No fijar rama definitiva por inferencia.','Estado original: CT. Propuesta funcional BORRADOR, no validada.','Recibo de haberes','CONTRADICCION_A_RESOLVER'::policy_rule_status,'No especificada',false,false,21,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R21');
