INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R24','Producto','Plazo máximo general','«Hasta 36 cuotas de manera estándar.» Resumen: «Plazo / Más de 36 cuotas / Revision».','cuotas, segmento y cargo','<=','36 cuotas (estándar)','Limitar oferta estándar; > 36 deriva a revisión según resumen','No convertir en rechazo definitivo ni en excepción aprobada sin validación.','Estado original: CT. Propuesta funcional BORRADOR, no validada.','Oferta + política','CONTRADICCION_A_RESOLVER'::policy_rule_status,'No especificada',false,true,24,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R24');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R25','Plazo por cargo','Activos, titulares','«Titular: Máximo aplicable según su segmento.»','cargo, segmento y catálogo de plazos','<=','máximo del segmento','Aplicar límite del segmento','No inventar un valor adicional. Mapeo de segmento pendiente.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Documentación laboral + política parametrizada','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,25,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R25');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R26','Plazo por cargo','Activos, interinos e interinos suplentes','«Interino / Interino Suplente: Máximo de 24 cuotas.»','condición activa, cargo y cuotas','<=','24 cuotas','Limitar plazo','No extender este límite a otros cargos.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Recibo/documentación laboral + oferta','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,26,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R26');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R27','Elegibilidad','Activos, reemplazantes','«Reemplazantes: Rechazo (no se otorgan préstamos a personas con este cargo).(Proximo de revisión)»','cargo y condición activa','=','reemplazante','Rechazo','La nota de próxima revisión no habilita a otorgar.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Documentación laboral/recibo','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,27,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R27');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R28','Elegibilidad','Activos, asesores','«Asesores: Rechazo (no se otorgan préstamos a personas con este cargo).»','cargo y condición activa','=','asesor','Rechazo','Excepciones no especificadas. Confirmar clasificación del cargo y mapeo.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Documentación laboral/recibo','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,28,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R28');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R29','Edad','CAJA/MUCI activos, hombres','«CAJA y MUCI (Activos): Hombres hasta 65 años; Mujeres hasta 60 años.» Control al terminar de abonar la última cuota.','condición activa, dato personal, nacimiento, calendario','<=','65 años al último vencimiento','Limitar alternativas de plazo','No evaluar sólo la edad actual; convención exacta pendiente.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Fuentes por mapear','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,29,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R29');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R30','Edad','CAJA/MUCI activas, mujeres','«CAJA y MUCI (Activos): Hombres hasta 65 años; Mujeres hasta 60 años.» Control al terminar de abonar la última cuota.','condición activa, dato personal, nacimiento, calendario','<=','60 años al último vencimiento','Limitar alternativas de plazo','No evaluar sólo la edad actual; convención exacta pendiente.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Fuentes por mapear','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,30,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R30');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R31','Edad','CAJA pasivos, hombres y mujeres','«CAJA (Pasivos): Hombres y Mujeres hasta 85 años.» «El límite de edad se calcula de forma que el socio no deba superar la edad máxima al terminar de abonar la última cuota.»','segmento, nacimiento y último vencimiento','<=','85 años al último vencimiento','Restringir alternativas de plazo','Convención de cumpleaños/igualdad pendiente. No extender a MUCI pasivos.','Estado original: PV. Propuesta funcional BORRADOR, no validada.','Fuentes por mapear','PENDIENTE_VALIDACION'::policy_rule_status,'No especificada',false,false,31,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R31');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R32','Deudas menores (soporte operativo) · SOPORTE OPERATIVO / FUERA DEL MOTOR','Casos especiales','«Si tiene una deuda menor a $500, no se realiza cancelación; el préstamo se cursa normalmente (consultarlo igualmente).»','saldo y tipo de deuda','<','500','No realizar cancelación; cursar con consulta','Fuera del motor. No asumir condonación. Exactamente $500: pendiente. Estado original OP/IN/PV.','Estado original: OP. Propuesta funcional BORRADOR, no validada.','Registros de deuda; alcance no precisado','NO_AUTOMATIZABLE_HOY'::policy_rule_status,'No especificada',false,true,32,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R32');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R33','Calendario (soporte operativo) · SOPORTE OPERATIVO / FUERA DEL MOTOR','Primer vencimiento','«Se coloca la fecha del primer vencimiento de acuerdo con la información brindada por el CUAD pisado.» (actual Diciembre y MÁS UNO Enero → tomar el último)','información de vencimientos de CUAD','=','vencimiento MÁS UNO informado por CUAD','Utilizar vencimiento indicado','Fuera del motor. No fijar mes ni día universal a partir del ejemplo. Estado original OP/PV.','Estado original: OP. Propuesta funcional BORRADOR, no validada.','CUAD','NO_AUTOMATIZABLE_HOY'::policy_rule_status,'No especificada',false,true,33,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R33');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R34','Cupo','Oferta evaluada (plantilla)','«El socio no posee cupo disponible para la oferta, tiene disponible $XXXXX. Reveer caso.»','cupo, cuota y oferta','<','cupo insuficiente (fórmula pendiente)','Informar disponible y revisar la alternativa','Plantilla útil para cupo; alcance pendiente. No inventar cupo = capital ni rechazar a la persona por una oferta incompatible.','Estado original: IN. Propuesta funcional BORRADOR, no validada.','Consulta operativa/CUAD y cálculo a validar','INCOMPLETA_EN_MANUAL'::policy_rule_status,'No especificada',false,true,34,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R34');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R35','Deuda interna','Solicitudes con operaciones previas (plantilla)','«Socio sobrepasa el límite que se le puede otorgar ya posee dos creditos que suman el total de $XXXXX otorgados. Lo maximo que puede solicitar es $XXXXX.»','operaciones y saldos internos, máximo aplicable','','sin definición suficiente','Control pendiente de endeudamiento interno','La plantilla no fija máximo de dos operaciones ni tope global de $6.000.000.','Estado original: IN. Propuesta funcional BORRADOR, no validada.','Fuente técnica pendiente','INCOMPLETA_EN_MANUAL'::policy_rule_status,'No especificada',false,false,35,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R35');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R36','Mora (soporte operativo) · SOPORTE OPERATIVO / FUERA DEL MOTOR','Discrepancia específica entre sistemas','«Si hay mora en Virmax pero en CUAD figura al día, no se cobrará mora (prioridad a CUAD).»','estados de la misma operación en VIMARX y CUAD','=','VIMARX con mora y CUAD al día','No cobrar esa mora; registrar observación','Fuera del motor. No extender la prioridad a otras discrepancias.','Estado original: OP. Propuesta funcional BORRADOR, no validada.','VIMARX + CUAD','NO_AUTOMATIZABLE_HOY'::policy_rule_status,'No especificada',false,true,36,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R36');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R37','Cobranza (soporte operativo) · SOPORTE OPERATIVO / FUERA DEL MOTOR','Irregularidad de cobros','«Si falta algún cobro, informar al Área de Cobranza para seguimiento.»','cobro esperado, recibido, período y operación','=','falta de cobro identificada','Informar a Cobranza','Fuera del motor. Sin rechazo automático.','Estado original: OP. Propuesta funcional BORRADOR, no validada.','Registros de cobro; mapeo pendiente','NO_AUTOMATIZABLE_HOY'::policy_rule_status,'No especificada',false,true,37,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R37');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R38','Mora (soporte operativo) · SOPORTE OPERATIVO / FUERA DEL MOTOR','Atraso confirmado en VIMARX y CUAD','«Más de 90 días de atraso: Cobrar solo los cargos Compensatorios.»','días de atraso y conceptos de cargos','>','90 días','Cobrar sólo cargos compensatorios','Fuera del motor. Fórmula pendiente; no es condonación.','Estado original: OP. Propuesta funcional BORRADOR, no validada.','VIMARX + CUAD','NO_AUTOMATIZABLE_HOY'::policy_rule_status,'No especificada',false,true,38,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R38');
INSERT INTO policy_rules (policy_id,code,block,segment,original_text,variable,operator,threshold,action_result,effect,conditions,data_source,definition_status,exceptions,allows_exception,manual_intervention,sort_order,source_excerpt) SELECT pid,'SF-R39','Mora (soporte operativo) · SOPORTE OPERATIVO / FUERA DEL MOTOR','Atraso confirmado en VIMARX y CUAD','«Menor a 90 días de atraso: No se cobrará ningún cargo adicional a la cuota.»','días de atraso, cuota y confirmación en ambos sistemas','<','90 días','No agregar cargos a la cuota','Fuera del motor. Tratamiento de cobro, no aprobación. Exactamente 90 días: sin definición.','Estado original: OP. Propuesta funcional BORRADOR, no validada.','VIMARX + CUAD','NO_AUTOMATIZABLE_HOY'::policy_rule_status,'No especificada',false,true,39,'SFE-V5 (Anexo A v0.2, 01/10/2026)' WHERE NOT EXISTS (SELECT 1 FROM policy_rules WHERE policy_id=pid AND code='SF-R39');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D01','Catálogo, segmentos y versión aplicable. ¿Qué códigos técnicos corresponden a las cuatro líneas? ¿Las variantes SANATORIO tienen condiciones propias? ¿Existe algún segmento MUCI pasivo habilitado y qué política lo regula? Confirmar que el archivo V5 es la versión a parametrizar, aunque el índice lo denomine V2.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D01');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D02','Significado de monto y límites. ¿Los topes se comparan con capital de la operación, monto solicitado u otro importe? ¿El desembolso neto después de cancelaciones debe controlarse por separado? No convertir el máximo por operación de $6.000.000 en un límite de endeudamiento total sin definición expresa.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D02');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D03','Cálculo financiero y control de CFTEA. Confirmar modalidad de la tasa mensual, sistema de amortización, conceptos incluidos, impuestos, redondeos, vigencia y responsable. ¿Quién calcula el CFTEA y qué respuesta genera superar el 131%? La tasa del 7,2% no demuestra por sí sola el cumplimiento del tope.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D03');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D04','Alcance de las exclusiones BCRA. ¿Excluir CELESOL 55281, FIAT 55277 y Médica 72104 implica excluir sólo importes, o también cantidad de entidades y situaciones? ¿Un socio con registros únicamente en esas entidades conserva la condición «con registro»?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D04');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D05','Deuda irregular exactamente igual a dos sueldos. El cuerpo admite menos de dos y rechaza más de dos; el cuadro final rechaza igual o más de dos. ¿Rechazo desde la igualdad o umbral estrictamente superior?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D05');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D06','Población, período y unidad de las variables BCRA. Precisar período, duplicados, entidades con saldo cero, unidad monetaria y fecha de corte. ¿Deuda irregular es saldo informado en situaciones 2 a 5 o sólo importe vencido? ¿Cómo se obtiene el neto usado en ambos múltiplos?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D06');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D07','Deuda total superior a diez sueldos y Comité. ¿El motor devuelve rechazo revisable o deriva directamente a Comité? Definir supuestos habilitantes, responsables, evidencia y alcance. La mención a Comité no es aprobación automática.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D07');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D08','Socio nuevo y ausencia de historial. Definir «socio nuevo» y «sin historial». El cuerpo limita a socios nuevos el tope de $1.000.000 y el mínimo de 18 cuotas; el resumen lo expresa para quien no tiene registro en Central. Confirmar alcance para recurrentes.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D08');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D09','Entidades presentes en el recibo. ¿Qué redacción rige (cuerpo vs cuadro final), cómo se cuentan entidades repetidas o del mismo grupo y qué significa «revisión de criterio» al superar cinco?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D09');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D10','Bases salariales y fórmula del cupo. Definir bruto, neto, descuentos totales y cuota a incorporar; exclusiones; varios recibos, cuotas sociales, retroactivos, descuentos a cancelar y reservas. ¿Fórmula operativa completa y relación con el cupo de CUAD?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D10');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D11','SMVM aplicable. Definir fuente, responsable de actualización, vigencia y período del SMVM (fecha de análisis, primer vencimiento u otro) y el comportamiento si no está disponible.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D11');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D12','Plazos habilitados y excepciones. ¿Qué cantidades de cuotas son ofertables dentro del intervalo? Definir el circuito de revisión al superar 36 y su relación con el máximo de 24 para interinos.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D12');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D13','Reemplazantes. El manual consigna rechazo y agrega «próximo de revisión». ¿Se mantiene el rechazo o existe una modificación aprobada?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D13');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D14','Edad al último vencimiento. Confirmar convención exacta (cumpleaños, edad cumplida, igualdad), dato fuente y segmentos cubiertos.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D14');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D15','Deudas menores a $500. ¿A qué deudas se refiere, saldo total o por operación, quién es consultado y qué ocurre con exactamente $500?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D15');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D16','CUAD, reservas y primer vencimiento. ¿Qué información puede consultarse antes de reservar el cupo y qué dato sólo existe después de «pisarlo»? Campo de vencimiento aplicable (actual / MÁS UNO), validación posterior y liberación de reservas. El motor no debe ejecutar reservas por evaluar.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D16');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D17','Endeudamiento interno y paralelos. Definir monto total permitido, saldo computado, entidades incluidas, cantidad máxima de paralelos y efecto de refinanciar o cancelar.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D17');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D18','Diferencias entre VIMARX y CUAD. ¿Cómo se cotejan operaciones, período y fecha; qué hacer si CUAD no responde o discrepan en otro sentido? ¿La comunicación a Cobranza detiene la originación?','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D18');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D19','Atraso de 90 días y cargos. Definir el caso de exactamente 90, base de cómputo, fórmula de cargos compensatorios, alcance y pago parcial.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D19');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D20','Documentación, cancelaciones y condiciones previas (S7, S8). Listado de documentos por etapa; conciliar el chequeo de mora en cancelaciones con deuda y pagos parciales; qué decide el motor y qué bloquea sólo firma, reserva o liquidación.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D20');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D21','Mapeo de datos e integraciones (toda la matriz). Para cada variable: sistema, campo, tipo, unidad, fecha, vigencia, método y evidencia. Definir la fuente de quiebras/concursos sin atribuirla al BCRA. Respuestas ante ausencia real, dato desconocido, consulta fallida y discrepancia.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D21');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D22','Consolidación de la decisión (toda la matriz). Prioridad entre rechazos, revisiones, faltantes y limitaciones; ¿se informan todos los motivos o se corta en el primero?; cuándo se recalcula la oferta. Diferenciar descarte de alternativa de rechazo de la persona.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D22');
INSERT INTO policy_questions (policy_id,code,question,status,answer) SELECT pid,'SF-D23','Validación final y correspondencia con SIISA (toda la matriz). Quién confirma la política y desde cuándo; nomenclatura y componentes reales de SIISA; publicación de versiones; registro de decisiones manuales; criterios de aceptación.','abierta','' WHERE NOT EXISTS (SELECT 1 FROM policy_questions WHERE policy_id=pid AND code='SF-D23');
INSERT INTO policy_question_rules (question_id,rule_id) SELECT qq.id, rr.id FROM policy_questions qq JOIN policy_rules rr ON rr.policy_id=pid AND rr.code = ANY(ARRAY['SF-R01','SF-R25','SF-R29','SF-R30','SF-R31']) WHERE qq.policy_id=pid AND qq.code='SF-D01' ON CONFLICT DO NOTHING;
INSERT INTO policy_question_rules (question_id,rule_id) SELECT qq.id, rr.id FROM policy_questions qq JOIN policy_rules rr ON rr.policy_id=pid AND rr.code = ANY(ARRAY['SF-R02','SF-R03','SF-R15']) WHERE qq.policy_id=pid AND qq.code='SF-D02' ON CONFLICT DO NOTHING;
INSERT INTO policy_question_rules (question_id,rule_id) SELECT qq.id, rr.id FROM policy_questions qq JOIN policy_rules rr ON rr.policy_id=pid AND rr.code = ANY(ARRAY['SF-R04','SF-R05','SF-R06']) WHERE qq.policy_id=pid AND qq.code='SF-D03' ON CONFLICT DO NOTHING;
INSERT INTO policy_question_rules (question_id,rule_id) SELECT qq.id, rr.id FROM policy_questions qq JOIN policy_rules rr ON rr.policy_id=pid AND rr.code = ANY(ARRAY['SF-R07','SF-R08','SF-R09','SF-R10','SF-R11','SF-R12','SF-R13']) WHERE qq.policy_id=pid AND qq.code='SF-D04' ON CONFLICT DO NOTHING;
INSERT INTO policy_question_rules (question_id,rule_id) SELECT qq.id, rr.id FROM policy_questions qq JOIN policy_rules rr ON rr.policy_id=pid AND rr.code = ANY(ARRAY['SF-R11']) WHERE qq.policy_id=pid AND qq.code='SF-D05' ON CONFLICT DO NOTHING;
