  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Inicio','Inicio de solicitud',640,0,1,'disenado',NULL,NULL,'{"description": "Recibe la solicitud a evaluar. Sin datos personales en el diseño.", "inputs": [{"name": "solicitud_id", "type": "entero", "required": true, "origin": "parametro", "notes": ""}, {"name": "cuil", "type": "texto", "required": true, "origin": "parametro", "notes": ""}, {"name": "convenio", "type": "texto", "required": true, "origin": "parametro", "notes": "Santa Fe"}, {"name": "datos_solicitud", "type": "texto", "required": true, "origin": "parametro", "notes": "monto, plazo, cargo, segmento"}, {"name": "ofertas", "type": "texto", "required": true, "origin": "parametro", "notes": "alternativas de monto/plazo"}], "outputs": [{"name": "solicitud_id", "type": "entero", "meaning": ""}, {"name": "cuil", "type": "texto", "meaning": ""}], "t": {}}'::jsonb,'solicitud_id, cuil, convenio, datos_solicitud, ofertas','solicitud_id, cuil','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Concurrente','Consolidación de fuentes (consulta en paralelo)',640,150,2,'disenado',NULL,NULL,'{"description": "Consulta en paralelo las fuentes. Concurrente sólo para consultas; no para aprobar alternativas.", "inputs": [{"name": "cuil", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "respuestas_fuentes", "type": "texto", "meaning": ""}], "t": {"sources": [{"name": "CORE"}, {"name": "OCR recibo (no verificado)"}, {"name": "CredixSA / BCRA"}, {"name": "CUAD Santa Fe"}, {"name": "PYPDatos"}, {"name": "VIMARX (por validar)"}], "availability": [{"codigo": "CORE", "fuente": "Core / Solicitudes", "categoria": "identificada en código", "detalle": "Campos de solicitud guardados en el Core. Contrato con SIISA sin verificar."}, {"codigo": "BCRA", "fuente": "CredixSA / BCRA", "categoria": "identificada en código", "detalle": "Consulta normalizada existente. Granularidad entidad/reporte a mapear; distinguir caché y antigüedad del dato; distinguir error de fuente de «sin registro»."}, {"codigo": "CUAD-SF", "fuente": "CUAD Santa Fe", "categoria": "identificada en código", "detalle": "Flow Kestra consulta_cuad existente (ACTIVOS). Recibe CUIL; devuelve ok, found, status, bruto, neto, cupo, afectado, disponible, deuda como STRINGS (requieren normalización numérica). Usa OCR de captcha, timeout y login; NO es OCR de recibo. Cupo general, no por línea."}, {"codigo": "PYP", "fuente": "Empleador PYPDatos", "categoria": "contrato pendiente", "detalle": "Consulta desarrollada; validar datos exactos devueltos."}, {"codigo": "VIMARX", "fuente": "VIMARX (historial)", "categoria": "contrato pendiente", "detalle": "Historial por adaptar."}, {"codigo": "OCR-RECIBO", "fuente": "OCR de recibo", "categoria": "no verificada", "detalle": "No verificado como conexión existente."}, {"codigo": "SMVM", "fuente": "Parámetro SMVM", "categoria": "no verificada", "detalle": "Origen y valor vigente aún no identificados."}, {"codigo": "ITS", "fuente": "ITS (clasificación de línea)", "categoria": "identificada en código", "detalle": "Sólo comprobada en el flujo posterior de firma/finalización (inferItsLine: ayt_nombre CAJA/MUCI, ayt_emp_id 1000 normal / 1003 sanatorio). No es criterio de originación."}]}}'::jsonb,'cuil','respuestas_fuentes','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'REST','Core / Solicitudes',40,320,3,'disenado',(SELECT id FROM policy_integrations WHERE code='CORE' LIMIT 1),NULL,'{"description": "Datos de la solicitud guardados. Contrato SIISA sin verificar.", "inputs": [{"name": "solicitud_id", "type": "entero", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "datos_solicitud", "type": "texto", "meaning": ""}, {"name": "estado_fuente_core", "type": "texto", "meaning": ""}], "t": {"request_desc": "solicitud_id", "response_desc": "campos de solicitud y ofertas", "source_ref": "CORE"}}'::jsonb,'solicitud_id','datos_solicitud, estado_fuente_core','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Parser','OCR de recibo (externo, no verificado)',280,320,4,'disenado',(SELECT id FROM policy_integrations WHERE code='OCR-RECIBO' LIMIT 1),NULL,'{"description": "Lectura del recibo de haberes. Conexión NO verificada.", "inputs": [{"name": "archivo_recibo", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "bruto_recibo", "type": "real", "meaning": ""}, {"name": "neto_recibo", "type": "real", "meaning": ""}, {"name": "descuentos_recibo", "type": "real", "meaning": ""}, {"name": "embargo_activo", "type": "booleano", "meaning": ""}, {"name": "entidades_recibo", "type": "texto", "meaning": ""}, {"name": "empleador", "type": "texto", "meaning": ""}, {"name": "cargo", "type": "texto", "meaning": ""}, {"name": "estado_fuente_ocr", "type": "texto", "meaning": ""}], "t": {"source_ref": "OCR-RECIBO", "response_desc": "campos propuestos, a confirmar"}}'::jsonb,'archivo_recibo','bruto_recibo, neto_recibo, descuentos_recibo, embargo_activo, entidades_recibo, empleador, cargo, estado_fuente_ocr','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'REST','CredixSA / BCRA',520,320,5,'disenado',(SELECT id FROM policy_integrations WHERE code='BCRA' LIMIT 1),NULL,'{"description": "Situación por entidad. Distinguir consulta válida sin registro, error de fuente y dato faltante; caché/antigüedad.", "inputs": [{"name": "cuil", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "deudas_por_entidad", "type": "texto", "meaning": ""}, {"name": "sin_registro_bcra", "type": "booleano", "meaning": ""}, {"name": "estado_fuente_bcra", "type": "texto", "meaning": ""}, {"name": "fecha_dato_bcra", "type": "texto", "meaning": ""}], "t": {"source_ref": "BCRA", "response_desc": "entidad, situación, monto, período"}}'::jsonb,'cuil','deudas_por_entidad, sin_registro_bcra, estado_fuente_bcra, fecha_dato_bcra','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
