  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'REST','PYPDatos empleador',1000,320,7,'disenado',(SELECT id FROM policy_integrations WHERE code='PYP' LIMIT 1),NULL,'{"description": "Datos del empleador. Validar campos exactos.", "inputs": [{"name": "cuil", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "empleador_pyp", "type": "texto", "meaning": ""}, {"name": "estado_fuente_pyp", "type": "texto", "meaning": ""}], "t": {"source_ref": "PYP"}}'::jsonb,'cuil','empleador_pyp, estado_fuente_pyp','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'REST','Historial VIMARX (por validar)',1240,320,8,'disenado',(SELECT id FROM policy_integrations WHERE code='VIMARX' LIMIT 1),NULL,'{"description": "Historial interno por adaptar.", "inputs": [{"name": "cuil", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "historial_vimarx", "type": "texto", "meaning": ""}, {"name": "estado_fuente_vimarx", "type": "texto", "meaning": ""}], "t": {"source_ref": "VIMARX"}}'::jsonb,'cuil','historial_vimarx, estado_fuente_vimarx','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Test Binario','¿Fuentes válidas y datos mínimos completos?',640,500,9,'disenado',NULL,NULL,'{"description": "Separa errores técnicos y datos faltantes de la decisión de política.", "inputs": [{"name": "estado_fuente_*", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "fuentes_completas", "type": "booleano", "meaning": ""}], "t": {"variable": "fuentes_completas", "operator": "=", "threshold": "verdadero", "true_label": "Continuar", "false_label": "Mitigación: revisión / no evaluable"}}'::jsonb,'estado_fuente_*','fuentes_completas','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Cálculo','Normalización y variables de evaluación',640,650,10,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R07' LIMIT 1),'{"description": "Normaliza strings de CUAD a números y construye variables BCRA aplicando exclusiones SF-R07.", "inputs": [{"name": "deudas_por_entidad", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "cuad_*", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "neto_recibo", "type": "real", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "deuda_irregular", "type": "real", "meaning": "SF-R10"}, {"name": "deuda_total", "type": "real", "meaning": ""}, {"name": "cant_entidades_con_deuda", "type": "entero", "meaning": ""}, {"name": "cupo_cuad_num", "type": "real", "meaning": "cupo general CUAD"}], "t": {"output_variable": "deuda_irregular, deuda_total, cant_entidades_con_deuda, cupo_cuad_num", "formula": "PENDIENTE (SF-D04, SF-D06, SF-D10): sumar situaciones 2-5 excluyendo 55281/55277/72104; parse numérico de CUAD", "dependencies": "SF-R07, SF-R10", "rule_codes": ["SF-R07", "SF-R10"]}}'::jsonb,'deudas_por_entidad, cuad_*, neto_recibo','deuda_irregular, deuda_total, cant_entidades_con_deuda, cupo_cuad_num','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Test Binario','Exclusiones explícitas (quiebra, embargo, empleador, cargo)',640,800,11,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R14' LIMIT 1),'{"description": "Grupo de reglas con efecto explícito de no operar. Abrir el inspector para ver cada código.", "inputs": [{"name": "quiebra_concurso", "type": "booleano", "required": true, "origin": "consulta", "notes": ""}, {"name": "embargo_activo", "type": "booleano", "required": true, "origin": "consulta", "notes": ""}, {"name": "empleador", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "cargo", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "exclusion_explicita", "type": "booleano", "meaning": ""}, {"name": "motivos_exclusion", "type": "texto", "meaning": ""}], "t": {"variable": "exclusion_explicita", "operator": "=", "threshold": "verdadero", "true_label": "Rechazo (condición explícita)", "false_label": "Continuar", "rule_codes": ["SF-R14", "SF-R17", "SF-R22", "SF-R27", "SF-R28"]}}'::jsonb,'quiebra_concurso, embargo_activo, empleador, cargo','exclusion_explicita, motivos_exclusion','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','Condiciones BCRA Santa Fe',640,950,12,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R08' LIMIT 1),'{"description": "SF-R08/09 continuar; SF-R11 > 2 netos rechazo (igualdad pendiente); SF-R12 ≥ 7 entidades rechazo; SF-R13 > 10 netos no opera en primera instancia (Comité por separado).", "inputs": [{"name": "deuda_irregular", "type": "real", "required": true, "origin": "consulta", "notes": ""}, {"name": "deuda_total", "type": "real", "required": true, "origin": "consulta", "notes": ""}, {"name": "cant_entidades_con_deuda", "type": "entero", "required": true, "origin": "consulta", "notes": ""}, {"name": "neto_recibo", "type": "real", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "estado_bcra", "type": "texto", "meaning": ""}, {"name": "motivos_bcra", "type": "texto", "meaning": ""}], "t": {"criteria": [{"name": "deuda_irregular / neto"}, {"name": "cant_entidades_con_deuda"}, {"name": "deuda_total / neto"}, {"name": "sin_registro_bcra"}], "outputs_desc": "continuar | rechazo explícito | revisión Comité", "table_status": "pendiente", "table_notes": "SF-D05 (igualdad) y SF-D07 (Comité) abiertas", "rule_codes": ["SF-R08", "SF-R09", "SF-R11", "SF-R12", "SF-R13"]}}'::jsonb,'deuda_irregular, deuda_total, cant_entidades_con_deuda, neto_recibo','estado_bcra, motivos_bcra','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','Capacidad por recibo y entidades',640,1100,13,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R18' LIMIT 1),'{"description": "SF-R18 descuentos post-cuota ≤ 50% bruto; SF-R19 remanente ≥ 1,5 SMVM; SF-R20/21 entidades del recibo (contradicción a resolver).", "inputs": [{"name": "bruto_recibo", "type": "real", "required": true, "origin": "consulta", "notes": ""}, {"name": "descuentos_recibo", "type": "real", "required": true, "origin": "consulta", "notes": ""}, {"name": "entidades_recibo", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "smvm_vigente", "type": "real", "required": true, "origin": "parametro", "notes": "origen no identificado"}], "outputs": [{"name": "estado_capacidad", "type": "texto", "meaning": ""}, {"name": "motivos_capacidad", "type": "texto", "meaning": ""}], "t": {"criteria": [{"name": "descuentos_post / bruto"}, {"name": "remanente / SMVM"}, {"name": "grupo CAJA/MUCI/MÉDICA presente"}, {"name": "cantidad de entidades"}], "outputs_desc": "continuar | revisión", "table_status": "pendiente", "table_notes": "SF-D09, SF-D10, SF-D11 abiertas", "rule_codes": ["SF-R18", "SF-R19", "SF-R20", "SF-R21"]}}'::jsonb,'bruto_recibo, descuentos_recibo, entidades_recibo, smvm_vigente','estado_capacidad, motivos_capacidad','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','Producto: monto, plazo, edad y condición financiera',640,1250,14,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R02' LIMIT 1),'{"description": "Monto $500.000–$6.000.000; nuevo sin historial ≤ $1.000.000 y ≥ 18 cuotas; plazo 18–36 (interino ≤ 24); edad al último vencimiento; tasa 7,2% mensual, sin cargos iniciales, CFTEA ≤ 131% (parámetros documentales).", "inputs": [{"name": "monto_solicitado", "type": "real", "required": true, "origin": "consulta", "notes": ""}, {"name": "plazo", "type": "entero", "required": true, "origin": "consulta", "notes": ""}, {"name": "cargo", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "fecha_nacimiento", "type": "texto", "required": true, "origin": "consulta", "notes": "dato no exportado"}, {"name": "sin_registro_bcra", "type": "booleano", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "restricciones_oferta", "type": "texto", "meaning": ""}], "t": {"criteria": [{"name": "monto"}, {"name": "plazo"}, {"name": "cargo"}, {"name": "edad al último vencimiento"}, {"name": "CFTEA"}], "outputs_desc": "límites por alternativa (no aprobación)", "table_status": "pendiente", "rule_codes": ["SF-R02", "SF-R03", "SF-R04", "SF-R05", "SF-R06", "SF-R15", "SF-R16", "SF-R23", "SF-R24", "SF-R25", "SF-R26", "SF-R29", "SF-R30", "SF-R31", "SF-R34", "SF-R35"]}}'::jsonb,'monto_solicitado, plazo, cargo, fecha_nacimiento, sin_registro_bcra','restricciones_oferta','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','Distribución a cuatro alternativas (fan-out conceptual)',640,1400,15,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R01' LIMIT 1),'{"description": "Fan-out conceptual del diseño: cada alternativa se evalúa por separado. Mapeo a nodos SIISA por confirmar; no se usa Concurrente para aprobar.", "inputs": [{"name": "estado_bcra", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "estado_capacidad", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "restricciones_oferta", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "alternativas", "type": "texto", "meaning": ""}], "t": {"criteria": [{"name": "línea"}], "outputs_desc": "CAJA | MUCI | SAN-CAJA | SAN-MUCI", "table_status": "pendiente", "table_notes": "Criterios de asignación por línea no definidos (SF-D01). ITS/ayt_emp_id sólo referencia downstream.", "rule_codes": ["SF-R01"]}}'::jsonb,'estado_bcra, estado_capacidad, restricciones_oferta','alternativas','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','CAJA — elegibilidad y monto posible',160,1580,16,'disenado',NULL,NULL,'{"description": "Alternativa HABERES CAJA 1 (PREMIUM). Primero elegibilidad, luego monto posible/cupo. Origen de cupo por línea: por confirmar (CUAD devuelve cupo general). Un cupo mensual no es capital máximo.", "inputs": [{"name": "alternativas", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "cupo_cuad_num", "type": "real", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "caja_elegibilidad", "type": "texto", "meaning": ""}, {"name": "caja_motivo", "type": "texto", "meaning": ""}, {"name": "caja_cupo_mensual", "type": "real", "meaning": ""}, {"name": "caja_monto_maximo_otorgable", "type": "real", "meaning": ""}, {"name": "caja_plazo_permitido", "type": "entero", "meaning": ""}, {"name": "caja_cuota_estimada", "type": "real", "meaning": ""}], "t": {"line_code": "CAJA", "criteria": [{"name": "elegibilidad"}, {"name": "cupo / monto posible"}], "outputs_desc": "APTO | NO_APTO | REVISION | NO_EVALUABLE", "table_status": "pendiente", "result_fields": ["elegibilidad (APTO|NO_APTO|REVISION|NO_EVALUABLE)", "motivo", "cupo_mensual", "monto_maximo_otorgable", "plazo_permitido", "cuota_estimada"]}}'::jsonb,'alternativas, cupo_cuad_num','caja_elegibilidad, caja_motivo, caja_cupo_mensual, caja_monto_maximo_otorgable, caja_plazo_permitido, caja_cuota_estimada','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','MUCI — elegibilidad y monto posible',500,1580,17,'disenado',NULL,NULL,'{"description": "Alternativa HABERES MUCI 1 (PREMIUM). Primero elegibilidad, luego monto posible/cupo. Origen de cupo por línea: por confirmar (CUAD devuelve cupo general). Un cupo mensual no es capital máximo.", "inputs": [{"name": "alternativas", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "cupo_cuad_num", "type": "real", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "muci_elegibilidad", "type": "texto", "meaning": ""}, {"name": "muci_motivo", "type": "texto", "meaning": ""}, {"name": "muci_cupo_mensual", "type": "real", "meaning": ""}, {"name": "muci_monto_maximo_otorgable", "type": "real", "meaning": ""}, {"name": "muci_plazo_permitido", "type": "entero", "meaning": ""}, {"name": "muci_cuota_estimada", "type": "real", "meaning": ""}], "t": {"line_code": "MUCI", "criteria": [{"name": "elegibilidad"}, {"name": "cupo / monto posible"}], "outputs_desc": "APTO | NO_APTO | REVISION | NO_EVALUABLE", "table_status": "pendiente", "result_fields": ["elegibilidad (APTO|NO_APTO|REVISION|NO_EVALUABLE)", "motivo", "cupo_mensual", "monto_maximo_otorgable", "plazo_permitido", "cuota_estimada"]}}'::jsonb,'alternativas, cupo_cuad_num','muci_elegibilidad, muci_motivo, muci_cupo_mensual, muci_monto_maximo_otorgable, muci_plazo_permitido, muci_cuota_estimada','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','SAN-CAJA — elegibilidad y monto posible',840,1580,18,'disenado',NULL,NULL,'{"description": "Alternativa HABERES CAJA 1 (PREMIUM) SANATORIO. Primero elegibilidad, luego monto posible/cupo. Origen de cupo por línea: por confirmar (CUAD devuelve cupo general). Un cupo mensual no es capital máximo.", "inputs": [{"name": "alternativas", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "cupo_cuad_num", "type": "real", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "san_caja_elegibilidad", "type": "texto", "meaning": ""}, {"name": "san_caja_motivo", "type": "texto", "meaning": ""}, {"name": "san_caja_cupo_mensual", "type": "real", "meaning": ""}, {"name": "san_caja_monto_maximo_otorgable", "type": "real", "meaning": ""}, {"name": "san_caja_plazo_permitido", "type": "entero", "meaning": ""}, {"name": "san_caja_cuota_estimada", "type": "real", "meaning": ""}], "t": {"line_code": "SAN-CAJA", "criteria": [{"name": "elegibilidad"}, {"name": "cupo / monto posible"}], "outputs_desc": "APTO | NO_APTO | REVISION | NO_EVALUABLE", "table_status": "pendiente", "result_fields": ["elegibilidad (APTO|NO_APTO|REVISION|NO_EVALUABLE)", "motivo", "cupo_mensual", "monto_maximo_otorgable", "plazo_permitido", "cuota_estimada"]}}'::jsonb,'alternativas, cupo_cuad_num','san_caja_elegibilidad, san_caja_motivo, san_caja_cupo_mensual, san_caja_monto_maximo_otorgable, san_caja_plazo_permitido, san_caja_cuota_estimada','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Matriz','SAN-MUCI — elegibilidad y monto posible',1180,1580,19,'disenado',NULL,NULL,'{"description": "Alternativa HABERES MUCI 1 (PREMIUM) SANATORIO. Primero elegibilidad, luego monto posible/cupo. Origen de cupo por línea: por confirmar (CUAD devuelve cupo general). Un cupo mensual no es capital máximo.", "inputs": [{"name": "alternativas", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "cupo_cuad_num", "type": "real", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "san_muci_elegibilidad", "type": "texto", "meaning": ""}, {"name": "san_muci_motivo", "type": "texto", "meaning": ""}, {"name": "san_muci_cupo_mensual", "type": "real", "meaning": ""}, {"name": "san_muci_monto_maximo_otorgable", "type": "real", "meaning": ""}, {"name": "san_muci_plazo_permitido", "type": "entero", "meaning": ""}, {"name": "san_muci_cuota_estimada", "type": "real", "meaning": ""}], "t": {"line_code": "SAN-MUCI", "criteria": [{"name": "elegibilidad"}, {"name": "cupo / monto posible"}], "outputs_desc": "APTO | NO_APTO | REVISION | NO_EVALUABLE", "table_status": "pendiente", "result_fields": ["elegibilidad (APTO|NO_APTO|REVISION|NO_EVALUABLE)", "motivo", "cupo_mensual", "monto_maximo_otorgable", "plazo_permitido", "cuota_estimada"]}}'::jsonb,'alternativas, cupo_cuad_num','san_muci_elegibilidad, san_muci_motivo, san_muci_cupo_mensual, san_muci_monto_maximo_otorgable, san_muci_plazo_permitido, san_muci_cuota_estimada','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Decisión','Dictamen final: vector de resultados por línea',640,1760,20,'disenado',NULL,NULL,'{"description": "Devuelve un resultado por línea + resumen consolidado. Resultados no acumulables automáticamente. Nombres de variables propuestos.", "inputs": [{"name": "resultado_caja", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "resultado_muci", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "resultado_san_caja", "type": "texto", "required": true, "origin": "consulta", "notes": ""}, {"name": "resultado_san_muci", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "resultados_por_linea", "type": "texto", "meaning": ""}, {"name": "resumen_consolidado", "type": "texto", "meaning": ""}], "t": {"verdict": "VECTOR POR LÍNEA (sin decisión automática)", "returned_variable": "resultados_por_linea", "rule_codes": []}}'::jsonb,'resultado_caja, resultado_muci, resultado_san_caja, resultado_san_muci','resultados_por_linea, resumen_consolidado','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Decisión','Mitigación: REVISION / NO_EVALUABLE',1240,800,21,'disenado',NULL,NULL,'{"description": "Falla de fuente, dato faltante, incongruencia o regla sin definir. Comité/excepciones se registran por separado. No ejecuta operaciones.", "inputs": [{"name": "motivo_mitigacion", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "estado", "type": "texto", "meaning": "REVISION | NO_EVALUABLE"}], "t": {"verdict": "REVISION / NO_EVALUABLE", "returned_variable": "estado"}}'::jsonb,'motivo_mitigacion','estado','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Decisión','Rechazo por condición explícita incumplida',40,950,22,'disenado',NULL,NULL,'{"description": "Sólo cuando una condición explícita del manual se incumple. No aplica a pasos fuera del motor.", "inputs": [{"name": "motivos_exclusion", "type": "texto", "required": true, "origin": "consulta", "notes": ""}], "outputs": [{"name": "estado", "type": "texto", "meaning": "NO_APTO"}], "t": {"verdict": "NO_APTO (condición explícita)", "returned_variable": "estado"}}'::jsonb,'motivos_exclusion','estado','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
  INSERT INTO policy_siisa_nodes (policy_id,trace_id,node_type,label,pos_x,pos_y,sort_order,impl_status,integration_id,rule_id,config_siisa,inputs,outputs,version_label,data_origin) VALUES (pid,tid,'Comentario','Fuera del motor (soporte operativo)',1240,1250,23,'disenado',NULL,(SELECT id FROM policy_rules WHERE policy_id=pid AND code='SF-R32' LIMIT 1),'{"description": "Pasos posteriores que el motor no ejecuta ni usa como rechazos.", "inputs": [], "outputs": [], "t": {"text": "Alta/baja de afiliados (CAJA: SOCIO CUOTA ADHERENTE 596; MUCI: ADHCSERV; registro en VIMARX); Cancelaciones y pre-cancelación de cuotas; informes de cancelación y refinanciación; Movimientos en CUAD: reserva («pisar» cupo), baja de cuotas, comprobantes; Generación y carga de AMV; Liquidación (LIQUIDACIÓN DIRECTA, «A LIQUIDAR», asiento); Transferencias y CBU de destino (Novedades/Observaciones); Cobros, mora y comunicación a Cobranza (SF-R36 a SF-R39); Deudas menores a $500 y primer vencimiento CUAD (SF-R32, SF-R33)", "steps": ["Alta/baja de afiliados (CAJA: SOCIO CUOTA ADHERENTE 596; MUCI: ADHCSERV; registro en VIMARX)", "Cancelaciones y pre-cancelación de cuotas; informes de cancelación y refinanciación", "Movimientos en CUAD: reserva («pisar» cupo), baja de cuotas, comprobantes", "Generación y carga de AMV", "Liquidación (LIQUIDACIÓN DIRECTA, «A LIQUIDAR», asiento)", "Transferencias y CBU de destino (Novedades/Observaciones)", "Cobros, mora y comunicación a Cobranza (SF-R36 a SF-R39)", "Deudas menores a $500 y primer vencimiento CUAD (SF-R32, SF-R33)"], "rule_codes": ["SF-R32", "SF-R33", "SF-R36", "SF-R37", "SF-R38", "SF-R39"]}}'::jsonb,'','','v0.1-diseño','blueprint Santa Fe V5') RETURNING id INTO nid;
