-- Seed Santa Fe V5 blueprint (BORRADOR). Generado por scripts/seeds/santa-fe-v5.py
DO $seed$
DECLARE pid uuid := 'e0141b77-3560-493b-abdf-bb5cd10a7ef2'; tid uuid; nid uuid; nodes jsonb := '{}'::jsonb;
BEGIN
