IF NOT EXISTS (SELECT 1 FROM policy_siisa_nodes WHERE trace_id=tid) THEN
  nodes := nodes || jsonb_build_object('inicio', nid);
  nodes := nodes || jsonb_build_object('conc', nid);
  nodes := nodes || jsonb_build_object('core', nid);
  nodes := nodes || jsonb_build_object('ocr', nid);
  nodes := nodes || jsonb_build_object('bcra', nid);
  nodes := nodes || jsonb_build_object('cuad', nid);
  nodes := nodes || jsonb_build_object('pyp', nid);
  nodes := nodes || jsonb_build_object('vimarx', nid);
  nodes := nodes || jsonb_build_object('fuentes_ok', nid);
  nodes := nodes || jsonb_build_object('norm', nid);
  nodes := nodes || jsonb_build_object('excl', nid);
  nodes := nodes || jsonb_build_object('bcra_eval', nid);
  nodes := nodes || jsonb_build_object('recibo', nid);
  nodes := nodes || jsonb_build_object('prod', nid);
  nodes := nodes || jsonb_build_object('fan', nid);
  nodes := nodes || jsonb_build_object('l_caja', nid);
  nodes := nodes || jsonb_build_object('l_muci', nid);
  nodes := nodes || jsonb_build_object('l_scaja', nid);
  nodes := nodes || jsonb_build_object('l_smuci', nid);
  nodes := nodes || jsonb_build_object('dict', nid);
  nodes := nodes || jsonb_build_object('mitig', nid);
  nodes := nodes || jsonb_build_object('rech', nid);
  nodes := nodes || jsonb_build_object('fuera', nid);
END IF;
END $seed$;
